D={f:pd.read_csv(f) for f in files}
def lag(x,T,dt):
    if T<=0: return x-x[0]
    a=dt/(T+dt); return lfilter([a],[1,-(1-a)],x-x[0])
dt=0.001
best=[]
for T1 in [0,0.02,0.05,0.1,0.2,0.4]:
  for T2 in [0,0.02,0.05,0.1,0.2,0.4,1.0]:
    A=[];b=[]
    for f in files:
        d=D[f];V=d.voltage_pu.values;Vs=d.voltage_setpoint_pu.values
